import numpy as np
def equation(t,P,params):
    a0,a1,a2,b0,b1,c0,c1,d0,d1,w=params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    e=np.exp(-0.5*t)
    return (a0+a1*e+a2*t*e) + P*(b0+b1*t*e) + P**2*(c0+c1*t*e) + d0*np.sin(w*t)+d1*np.cos(w*t)
